import { db } from '../db';
import { orders, orderItems, products } from '../db/schema';
import { eq } from 'drizzle-orm';

export interface CheckoutInput {
  userId: string;
  items: Array<{ productId: string; quantity: number }>;
}

export async function processCheckout(input: CheckoutInput) {
  return await db.transaction(async (tx) => {
    let totalCents = 0;
    for (const item of input.items) {
      const [product] = await tx.select().from(products).where(eq(products.id, item.productId));
      if (!product || product.stock < item.quantity) {
        throw new Error(`Insufficient stock for product ${item.productId}`);
      }
      totalCents += product.priceCents * item.quantity;
      await tx.update(products).set({ stock: product.stock - item.quantity }).where(eq(products.id, item.productId));
    }
    const [order] = await tx.insert(orders).values({ userId: input.userId, totalCents, status: 'paid' }).returning();
    return order;
  });
}
